// findings.hpp -- a finding as structured data, and the report you can hand someone.
//
// WHY THIS EXISTS
//
// Until now every finding this project makes existed only as text on a terminal. That is enough to prove the
// detectors work and useless as a deliverable: the wedge in MISSION.md is a paid audit, and an audit ends with a
// document somebody can read, circulate, disagree with, and act on.
//
// The findings are NOT re-parsed out of the terminal output. A report generated by scraping a human-readable
// stream is a second implementation of the analysis that can silently disagree with the first, and this project
// has already paid for that class of mistake more than once. Each detector records a Finding once, and the two
// renderings -- terminal and report -- are two views of the same data.
//
// WHAT A REPORT MUST CONTAIN TO BE HONEST
//
//   * provenance: which file, its SHA-256, which tool, when. A finding nobody can trace to a document is gossip.
//   * every finding located to a LINE, with the document's own words quoted back. The customer must be able to
//     open their worksheet and see the row.
//   * what would CLOSE each finding, because a finding with no remedy is a complaint.
//   * THE CHECKS THAT FOUND NOTHING. This is the part most tools omit and it is the part that makes the rest
//     mean anything: a report listing three findings could be a thorough audit or a tool that only knows three
//     things. Naming the silent checks is what turns silence into evidence.
//   * what was NOT checked at all. The independence check implements a fragment of one CCPS criterion; a reader
//     who assumes it covers all of them has been misled by omission.
//
// WHAT IT MUST NOT CONTAIN
//
// A verdict, a score, or a prescribed remedy. Compiling a suggested fix and measuring it, rather than reasoning
// about it, is a lesson this project paid for: advice to merge two duplicated claims in a HAZOP would have made
// the plant shut down LESS often than leaving them separate. Remedies here name what would SETTLE a question,
// never what the engineer should decide.

#ifndef QUORUM_CASEBOOK_FMEA_FINDINGS_HPP
#define QUORUM_CASEBOOK_FMEA_FINDINGS_HPP

#include <algorithm>
#include <cstdio>
#include <map>
#include <string>
#include <vector>

namespace quorum::findings {

/// How much of the document's conclusion rests on this.
///
/// Deliberately three coarse bands rather than a score. A number implies a precision that a keyword match on
/// engineering prose does not have, and a customer who sees "7.4/10" will argue about the 7.4 instead of reading
/// the finding.
enum class Weight {
    Conclusion,  ///< what the study itself concludes, restated so a reader need not recompute it.
    Arithmetic,  ///< the document contradicts itself. Not a matter of opinion.
    Structural,  ///< the document's conclusion depends on something it does not state.
    Observation, ///< worth knowing; the document may be entirely right.
};

struct Finding {
    std::string kind;     ///< short label, shared with the terminal output: "ARITHMETIC", "NOT INDEPENDENT"
    Weight weight = Weight::Observation;
    int line = 0;         ///< line in the source document, 0 if the finding is about the document as a whole
    std::string subject;  ///< what it is about, in the document's own words
    std::string detail;   ///< the specifics, including numbers
    std::string why;      ///< why it matters, once per kind
    std::string closes;   ///< what would settle it. Never what to decide.
};

/// A check that ran. Recorded whether or not it fired, because silence is only evidence if it is named.
struct Check {
    std::string kind;
    std::string question;  ///< what it asks, in one line
    int fired = 0;
};

class Report {
public:
    void check(const std::string& kind, const std::string& question) {
        for (const Check& c : checks_) { if (c.kind == kind) { return; } }
        checks_.push_back(Check{kind, question, 0});
    }

    void add(Finding f) {
        for (Check& c : checks_) { if (c.kind == f.kind) { ++c.fired; } }
        items_.push_back(std::move(f));
    }

    /// A limit of the analysis itself: something a reader might reasonably assume was checked and was not.
    void limit(const std::string& text) { limits_.push_back(text); }

    /// A figure the document states and the tool independently recomputed to the same value.
    void confirmed(const std::string& what, const std::string& value) {
        confirmations_.push_back(what + ": " + value);
    }

    std::size_t size() const { return items_.size(); }

    int fired(const std::string& kind) const {
        for (const Check& c : checks_) { if (c.kind == kind) { return c.fired; } }
        return 0;
    }

    /// Write the report. `source` is the worksheet path, `sha` its digest, `tool` the importer's name.
    bool markdown(const std::string& path, const std::string& source, const std::string& sha,
                  const std::string& tool, const std::string& provenance,
                  const std::string& command) const {
        std::FILE* f = std::fopen(path.c_str(), "w");
        if (f == nullptr) { return false; }

        std::fprintf(f, "# Safety document review: %s\n\n", source.c_str());
        std::fprintf(f, "| | |\n|---|---|\n");
        std::fprintf(f, "| document | `%s` |\n", source.c_str());
        std::fprintf(f, "| SHA-256 | `%s` |\n", sha.c_str());
        std::fprintf(f, "| reviewed by | `%s` (quorum) |\n", tool.c_str());
        std::fprintf(f, "| findings | %zu |\n", items_.size());
        if (!provenance.empty()) {
            std::fprintf(f, "\n%s\n", provenance.c_str());
        }

        std::fprintf(f,
            "\n> Every finding below was derived from the worksheet as written. None of them changes a number in\n"
            "> your document, and none of them is a verdict. Each one names a place where the document's own\n"
            "> conclusion rests on something the document does not state, and says what would settle it.\n");

        if (!confirmations_.empty()) {
            std::fprintf(f, "\n## What this review established\n\n");
            std::fprintf(f,
                "Listed first because a review that reports only problems gives no evidence it understood the\n"
                "document. Where the document states a figure, it was recomputed independently and agrees.\n\n");
            for (const std::string& c : confirmations_) {
                std::fprintf(f, "- %s\n", c.c_str());
            }
        }

        // Findings, heaviest first. Within a weight, in document order, so a reader can work down their file.
        static const Weight order[] = {Weight::Conclusion, Weight::Arithmetic, Weight::Structural,
                                       Weight::Observation};
        static const char* const titles[] = {
            "The study's own conclusion",
            "The document contradicts itself",
            "The conclusion depends on something unstated",
            "Worth knowing",
        };
        static const char* const blurbs[] = {
            "Restated, not discovered. A competent study reaches this itself, and the well-run ones say so plainly.\n"
            "It is repeated here so a reader can see where the study landed without recomputing it, and so that a\n"
            "conclusion cannot quietly go missing between the worksheet and the decision it informs.",
            "These are not matters of opinion. The document supplies both the inputs and the answer, and they\n"
            "disagree. A wrong exponent is one character in a spreadsheet and an order of magnitude in the\n"
            "conclusion.",
            "The document may be entirely correct about each of these. What it does not do is say so, which means\n"
            "the conclusion cannot be checked by a reader -- or by the next engineer to inherit it.",
            "Neither errors nor omissions. Each is a property of the document worth being aware of when deciding\n"
            "how much weight its conclusion carries.",
        };
        for (std::size_t w = 0; w < 4; ++w) {
            std::vector<const Finding*> group;
            for (const Finding& i : items_) { if (i.weight == order[w]) { group.push_back(&i); } }
            if (group.empty()) { continue; }
            std::stable_sort(group.begin(), group.end(),
                             [](const Finding* a, const Finding* b) { return a->line < b->line; });
            std::fprintf(f, "\n## %s\n\n%s\n", titles[w], blurbs[w]);
            int n = 0;
            for (const Finding* i : group) {
                ++n;
                std::fprintf(f, "\n### %s %d — %s\n\n", i->kind.c_str(), n, i->subject.c_str());
                if (i->line > 0) {
                    std::fprintf(f, "**Where:** line %d of `%s`\n\n", i->line, source.c_str());
                } else {
                    std::fprintf(f, "**Where:** the document as a whole\n\n");
                }
                if (!i->detail.empty()) {
                    std::fprintf(f, "```\n%s\n```\n\n", i->detail.c_str());
                }
                if (!i->why.empty())    { std::fprintf(f, "%s\n\n", i->why.c_str()); }
                if (!i->closes.empty()) { std::fprintf(f, "**What would settle it:** %s\n", i->closes.c_str()); }
            }
        }

        // ── the part that makes the rest mean something ──────────────────────
        std::fprintf(f, "\n## Checks that found nothing\n\n");
        std::fprintf(f,
            "A review listing %zu finding(s) could be a thorough one or a tool that only knows %zu things. Every\n"
            "check below ran against this document. The ones that found nothing are evidence, not absence of\n"
            "effort.\n\n", items_.size(), items_.size());
        std::fprintf(f, "| check | question asked | found |\n|---|---|---|\n");
        for (const Check& c : checks_) {
            std::fprintf(f, "| %s | %s | %s |\n", c.kind.c_str(), c.question.c_str(),
                         c.fired == 0 ? "nothing" : "see above");
        }

        if (!limits_.empty()) {
            std::fprintf(f, "\n## What was NOT checked\n\n");
            std::fprintf(f,
                "Listed because a reader who assumes otherwise has been misled by omission, which is the failure\n"
                "this whole tool exists to prevent.\n\n");
            for (const std::string& l : limits_) { std::fprintf(f, "- %s\n", l.c_str()); }
        }

        // The exact command, not an approximation of it. A reproduction line a reader cannot paste is worse than
        // none: it invites them to conclude the report is careless about the things it cannot see either.
        std::fprintf(f, "\n## Reproducing this\n\n```\n%s\n```\n\n", command.c_str());
        // Worded precisely, because this is a claim about the tool made IN the deliverable. The findings are
        // deterministic; the file is not byte-identical run to run, because the command line above names wherever
        // the output was sent. Claiming the stronger property would have been a false statement in a document
        // handed to a customer -- caught by the test that took the claim at its word and diffed two runs.
        std::fprintf(f,
            "The findings are deterministic: the same worksheet yields the same findings, in the same order, with\n"
            "no reliance on machine state or timing. Only the command line above differs between runs, because it\n"
            "names wherever you sent the output.\n"
            "\n"
            "If the document changes, the SHA-256 above changes with it, so a report can always be matched to the\n"
            "revision it describes -- and a report whose digest does not match the file in front of you is\n"
            "describing a different revision, which is worth more than it sounds.\n");
        std::fclose(f);
        return true;
    }

private:
    std::vector<Finding> items_;
    std::vector<Check> checks_;
    std::vector<std::string> limits_;
    std::vector<std::string> confirmations_;
};

}  // namespace quorum::findings

#endif  // QUORUM_CASEBOOK_FMEA_FINDINGS_HPP
